content.text:
{
  "name": "Timepix4 像素探测器",
  "name_en": "Timepix4 pixel detector",
  "manufacturer": "",
  "description": "用于实验中 Timepix4 像素探测器的控制与数据采集，可加载配置、设置像素阈值/掩膜/测试参数、管理以太网数据过滤，并启动、停止和记录探测数据。",
  "description_en": "Controls a Timepix4 pixel detector for laboratory data acquisition, including loading configuration, setting pixel threshold/mask/test parameters, managing Ethernet data filtering, and starting, stopping, and recording detector data.",
  "actions": [
    {
      "action_name": "auto-config",
      "description": "按当前配置对 Timepix4 探测器执行配置。",
      "description_en": "Apply the current configuration to the Timepix4 detector."
    },
    {
      "action_name": "auto-setupAcquisition",
      "description": "创建并设置探测器的数据采集对象或采集流程。",
      "description_en": "Create and set up the detector acquisition object or acquisition pipeline."
    },
    {
      "action_name": "auto-setConfigClass",
      "description": "选择用于管理探测器设置的配置类。",
      "description_en": "Select the configuration class used to manage detector settings."
    },
    {
      "action_name": "auto-loadConfig",
      "description": "从配置类加载探测器配置和 DAC 设置。",
      "description_en": "Load detector configuration and DAC settings from the selected configuration class."
    },
    {
      "action_name": "auto-setupDevice",
      "description": "初始化探测器可用的采集参数。",
      "description_en": "Initialize valid acquisition parameters for the detector."
    },
    {
      "action_name": "auto-acquisition",
      "description": "获取当前采集对象，以便直接调整采集参数。",
      "description_en": "Access the current acquisition object for direct adjustment of acquisition parameters."
    },
    {
      "action_name": "auto-pauseHeartbeat",
      "description": "暂停探测器心跳通信。",
      "description_en": "Pause the detector heartbeat communication."
    },
    {
      "action_name": "auto-resumeHeartbeat",
      "description": "恢复探测器心跳通信。",
      "description_en": "Resume the detector heartbeat communication."
    },
    {
      "action_name": "auto-devIdToString",
      "description": "将设备 ID 转换为可读字符串。",
      "description_en": "Convert the device ID into a human-readable string."
    },
    {
      "action_name": "auto-deviceName",
      "description": "获取探测器设备名称。",
      "description_en": "Get the detector device name."
    },
    {
      "action_name": "auto-setEthernetFilter",
      "description": "设置探测器以太网数据包过滤规则。",
      "description_en": "Set the Ethernet packet filter for the detector data stream."
    },
    {
      "action_name": "auto-resetPixels",
      "description": "清除像素配置。",
      "description_en": "Clear the pixel configuration."
    },
    {
      "action_name": "auto-pixelThreshold",
      "description": "获取或设置逐像素阈值配置。",
      "description_en": "Get or set the per-pixel threshold configuration."
    },
    {
      "action_name": "auto-pixelMask",
      "description": "获取或设置逐像素掩膜配置。",
      "description_en": "Get or set the per-pixel mask configuration."
    },
    {
      "action_name": "auto-pixelTest",
      "description": "获取或设置逐像素测试配置。",
      "description_en": "Get or set the per-pixel test configuration."
    },
    {
      "action_name": "auto-uploadPixels",
      "description": "将本地像素配置上传到探测器。",
      "description_en": "Upload the local pixel configuration to the detector."
    },
    {
      "action_name": "auto-refreshPixels",
      "description": "从探测器读取像素配置并刷新到本地。",
      "description_en": "Read the pixel configuration from the detector and refresh the local copy."
    },
    {
      "action_name": "auto-start",
      "description": "启动探测器采集。",
      "description_en": "Start detector acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止探测器采集。",
      "description_en": "Stop detector acquisition."
    },
    {
      "action_name": "auto-start_recording",
      "description": "开始将探测器数据记录到指定路径。",
      "description_en": "Start recording detector data to the specified path."
    },
    {
      "action_name": "auto-stop_recording",
      "description": "停止记录探测器数据。",
      "description_en": "Stop recording detector data."
    },
    {
      "action_name": "auto-Vthreshold_fine",
      "description": "获取或设置细调阈值参数。",
      "description_en": "Get or set the fine threshold parameter."
    },
    {
      "action_name": "auto-Vthreshold_coarse",
      "description": "获取或设置粗调阈值参数。",
      "description_en": "Get or set the coarse threshold parameter."
    }
  ],
  "tag_hints": [
    "pixel detector",
    "Timepix4",
    "radiation detection",
    "per-pixel configuration",
    "threshold tuning",
    "Ethernet data acquisition",
    "detector recording"
  ]
}

